// WF-3 "Plan drafts" (Code node, Run Once for All Items).
// Reads the three Supabase lookups and decides what to write this run, newest work first:
//   1. follow-ups  – leads emailed N days ago who have not replied (step 2, then step 3)
//   2. first email – qualified leads with an email that have never had a draft
//   3. DM          – qualified leads with no email but an X or LinkedIn profile
// Output: one item per draft with the Groq prompt ready (system + user) and the row fields to save.

const cfg = $('Settings').first().json
const MIN_SCORE = Number(cfg.min_score) || 0
const FOLLOW_UP_DAYS = String(cfg.follow_up_days || '4,7').split(',').map(n => Number(n.trim())).filter(n => n > 0)
const MAX_STEP = 1 + FOLLOW_UP_DAYS.length
const DAY = 86400000
const PENDING = new Set(['pending_review', 'scheduled', 'approved'])
// Scheduled runs keep at most one day's sending (daily_max) of email drafts waiting, so nothing piles up.
// Clicking "Draft new emails" in the dashboard is not capped.
const fromDashboard = $('Dashboard: Draft outreach').isExecuted
const waiting = $('Waiting drafts').all().filter(i => i.json && i.json.id).length
// Daily minimum (Autopilot only): if today's sent + waiting emails fall short of daily_min, draft enough to close
// the gap, also for leads scoring below min_score (down to fill_min_score; "Fetch leads to draft" includes them).
// WF-3b then sends drafts still waiting for review until the minimum is reached.
const sentToday = $('Sent today').all().filter(i => i.json && i.json.id).length
const FILL = cfg.autopilot_mode === 'auto' && cfg.paused !== true && Number(cfg.daily_min) > 0
let shortfall = FILL ? Math.max(0, Number(cfg.daily_min) - sentToday - waiting) : 0
let firstEmailRoom = fromDashboard ? Infinity : Math.max(0, (Number(cfg.daily_max) || 20) - waiting, shortfall)
const MAX = Math.max(Number(cfg.batch_size) || 10, Math.min(shortfall, 30))

const rows = name => $(name).all().map(i => i.json).filter(l => l && l.id)
const hookOf = l => String(l.ai_reasoning || '').match(/Hook:\s*(.+)/i)?.[1]?.trim() || null
const firstName = l => {
  const f = String(l.name || '').trim().split(/\s+/)[0] || ''
  // Only a real-looking name ("Maya"); handles like "klntsky" or "jdoe42" fall back to "Hi <Company> team,".
  return /^[A-Z](?=.*[a-z])[A-Za-z'-]+$/.test(f) ? f : null
}
const facts = l => [
  'Founder first name: ' + (firstName(l) || 'unknown'),
  'Founder role: ' + (l.founder_role || 'unknown'),
  'Company: ' + (l.company || '?'),
  'Website: ' + (l.website || l.company_domain || '?'),
  'Launched: ' + (l.launched_at || 'unknown') + ' (found on ' + l.source + ')',
  'Homepage has a product video: ' + (l.has_video === null || l.has_video === undefined ? 'unknown' : l.has_video ? 'yes' : 'no'),
  'Signals: ' + (Array.isArray(l.signals) ? l.signals.join(', ') : ''),
  'Hook (a specific detail about them): ' + (hookOf(l) || 'none'),
  'What they built / said: ' + String(l.bio || l.post_content || '').slice(0, 1200),
]

// What Bear Studios is, from the one-pager. The model may only use these facts about us.
const STUDIO = [
  'ABOUT US — Bear Studios (bearstudios.in): motion design and film for startups.',
  'We make two things: (1) Explainer videos — complex products explained simply, precise motion, clean UI animation and tight scripting, so investors and users get it in under 90 seconds; (2) Product launch videos / promos — smooth, cinematic, data-driven motion graphics that make a product feel inevitable.',
  'How we work: Brief, Research, Script, Storyboard, Styleframes, Production, Delivery. Two review rounds. Turnaround: explainer 7-12 days, launch video 10-14 days.',
  'Every video is delivered in 4K in 16:9 (web/YouTube), 9:16 (Reels/Shorts) and 1:1 (LinkedIn/ads). Each client gets a live ClickUp workspace for briefs, storyboards, feedback and deliverables.',
  'Our standard: obsessive craft — the details nobody notices consciously but everyone feels.',
].join('\n')

const VOICE =
  'VOICE: a founder writing to another founder. Confident, warm, specific, concise. Short sentences. Plain text only: no markdown, no bullet points, no emojis, no exclamation marks. ' +
  'Never use: "I hope this finds you well", "I came across", "I wanted to reach out", "just checking in", "touch base", "circle back", "synergy", "game-changer", "revolutionize", "leverage", "cutting-edge", "take it to the next level". ' +
  'Never invent facts, numbers, client names, results or prices. Only use facts given about them and about us. ' +
  'Do NOT write a greeting sign-off or signature (no "Best", "Cheers", name or company at the end) — it is added automatically.'

const SYS_FIRST = [
  'You write first-touch cold emails for Bear Studios to the founder of a startup that just launched.',
  STUDIO,
  VOICE,
  'STRUCTURE (4 short paragraphs, 90-140 words in total):',
  '1. Greeting line: "Hi <first name>," (or "Hi <Company> team," if the name is unknown).',
  '2. One or two sentences showing you actually looked: a specific, genuine observation about what they built or launched (use the hook). No generic praise.',
  '3. The gap and the idea: why a video matters for them right now (e.g. new visitors decide in seconds, the product is hard to grasp from text, launch momentum fades fast) and ONE concrete video idea tailored to their product — describe what the video would show in a sentence. Pick the service that fits: no homepage video -> a 60-90 second explainer; just launched -> a launch film plus vertical and square cuts for social.',
  '4. At most one proof point about how we work (e.g. delivered in 7-12 days, or 4K in every format, or a live workspace) — only if it helps.',
  '5. A low-friction close: a single soft question such as "Would a 15-minute call next week be useful?" or "Want me to sketch a rough storyline for <Company>?". Then a final line exactly: "I\'ve attached a one-pager on how we work."',
  'SUBJECT: 3-6 words, specific to them, sentence case or lowercase, no clickbait, no "quick question".',
  'Output ONLY JSON: {"subject": "...", "body": "..."} where body uses \\n\\n between paragraphs.',
].join('\n')

const SYS_FOLLOW = [
  'You write a short follow-up to a cold email from Bear Studios that got no reply. It is sent as a reply in the same Gmail thread, so do not repeat the original pitch or re-introduce us.',
  STUDIO,
  VOICE,
  'Follow-up step 2 (40-80 words): "Hi <first name>," then add genuine value — one new, concrete storyline idea for a video about their product (what the first seconds would show, what the viewer understands by the end). Close with a soft question.',
  'Follow-up step 3, the last one (30-60 words): "Hi <first name>," then a polite close-the-loop note: you will not follow up again, the door stays open, they can reply any time or book a call at calendly.com/bearstudios-co/30min. No guilt-tripping.',
  'Output ONLY JSON: {"subject": "Re: <original subject>", "body": "..."}',
].join('\n')

const SYS_DM = [
  'You write a short direct message (X or LinkedIn) from Karthikeya at Bear Studios to the founder of a startup that just launched.',
  STUDIO,
  VOICE,
  'DM rules: 35-70 words, casual but sharp, 2-3 short sentences. Start with "Hey <first name>" (or "Hey" if unknown). Mention one specific thing about what they launched, one concrete video idea for it, then ask if they would like to see a couple of examples. No links, no sign-off.',
  'Output ONLY JSON: {"subject": "DM to <company>", "body": "..."}',
].join('\n')

const plan = []
const seenLead = new Set()
const seenEmail = new Set()
const add = item => {
  if (plan.length >= MAX || seenLead.has(item.lead_id)) return
  if (item.email && seenEmail.has(item.email.toLowerCase())) return
  seenLead.add(item.lead_id)
  if (item.email) seenEmail.add(item.email.toLowerCase())
  plan.push(item)
}

// 1. Follow-ups
const now = Date.now()
for (const l of rows('Fetch follow-ups')) {
  const queue = Array.isArray(l.outreach_queue) ? l.outreach_queue : []
  if (!l.email || queue.some(q => PENDING.has(q.status))) continue
  const sent = queue.filter(q => q.status === 'sent' && q.sent_at && (q.channel || 'email') === 'email')
  if (!sent.length) continue
  const last = sent.reduce((a, b) => ((b.sequence_step || 1) > (a.sequence_step || 1) ? b : a))
  const step = (last.sequence_step || 1) + 1
  if (step > MAX_STEP) continue
  const waitDays = FOLLOW_UP_DAYS[step - 2]
  if ((now - Date.parse(last.sent_at)) / DAY < waitDays) continue
  const first = sent.find(q => (q.sequence_step || 1) === 1) || last
  const before = plan.length
  add({
    kind: 'followup', lead_id: l.id, email: l.email, channel: 'email', sequence_step: step, ai_score: l.ai_score,
    system: SYS_FOLLOW,
    user: [
      `This is follow-up step ${step} of ${MAX_STEP}.`,
      `Original subject: ${first.subject}`,
      `Original email:\n${String(first.body || '').slice(0, 1500)}`,
      ...facts(l),
    ].join('\n'),
    fallback_subject: /^re:/i.test(first.subject || '') ? first.subject : `Re: ${first.subject}`,
  })
  if (plan.length > before) shortfall--
}

// 2. First emails
for (const l of rows('Fetch leads to draft')) {
  if (!l.email || (Array.isArray(l.outreach_queue) && l.outreach_queue.length)) continue
  if (firstEmailRoom <= 0) break
  // Leads under min_score are only here to make up a daily-minimum shortfall.
  if ((Number(l.ai_score) || 0) < MIN_SCORE && shortfall <= 0) continue
  const before = plan.length
  add({ kind: 'first', lead_id: l.id, email: l.email, channel: 'email', sequence_step: 1, ai_score: l.ai_score, system: SYS_FIRST, user: facts(l).join('\n') })
  if (plan.length > before) { firstEmailRoom--; shortfall-- }
}

// 3. DMs for leads without an email
if (cfg.draft_dms !== false && String(cfg.draft_dms) !== 'false') {
  for (const l of rows('Fetch DM leads')) {
    if (l.email || !(l.x_handle || l.linkedin_url) || (Array.isArray(l.outreach_queue) && l.outreach_queue.length)) continue
    add({ kind: 'dm', lead_id: l.id, email: null, channel: 'dm', sequence_step: 1, system: SYS_DM, user: facts(l).join('\n') })
  }
}

return plan.map(json => ({ json }))

// WF-3 "Build drafts" (Code node, Run Once for All Items).
// Input: the Groq response(s) for the current loop batch (one draft at a time); each is matched back to its "Plan drafts" item.
// Output: ONE item { rows: [...outreach_queue rows], drafted, failed: [...] }.

// The model is asked for JSON only; take the first {...} block in case it adds any text around it.
const parseJson = text => {
  const raw = String(text || '').trim()
  const block = raw.match(/\{[\s\S]*\}/)
  return JSON.parse(block ? block[0] : raw)
}
// n8n reports API errors as '400 - {"error":{"message":"..."}}'; keep the readable part.
const errorText = err => {
  const text = String((err && err.message) || err || 'unknown error')
  return (text.match(/"message"\s*:\s*"((?:[^"\\]|\\.)*)"/) || [])[1] || text
}

const cfg = $('Settings').first().json
const plan = $('Plan drafts').all().map(i => i.json)
const planFor = i => {
  try {
    return $('Plan drafts').itemMatching(i).json
  } catch {
    return plan[i]
  }
}

// One fixed, professional ending for every email (the model is told not to write its own).
const SIGNATURE = [cfg.sign_off || 'Cheers,', cfg.sender_name || 'Karthikeya Popuri', cfg.company_name || 'Bear Studios', cfg.website || 'bearstudios.in']
  .filter(Boolean)
  .join('\n')
const ATTACH_LINE = "I've attached a one-pager on how we work."
const SIGN_OFF = /^(best|cheers|thanks|thank you|regards|warm regards|kind regards|best regards|sincerely|talk soon)[,.!]?$/i

// Drop any sign-off the model added anyway, so the signature never appears twice.
const stripSignOff = text => {
  const lines = text.split('\n')
  for (let i = Math.max(0, lines.length - 6); i < lines.length; i++) {
    if (SIGN_OFF.test(lines[i].trim())) return lines.slice(0, i).join('\n').trimEnd()
  }
  return lines
    .filter((line, i) => !(i >= lines.length - 3 && /karthikeya|bear studios|bearstudios\.in/i.test(line) && line.trim().split(/\s+/).length <= 4))
    .join('\n')
    .trimEnd()
}

const finishEmail = (body, kind) => {
  let text = stripSignOff(body)
  if (kind === 'first') {
    text = text.replace(/\n*I['’]ve attached a one-pager on how we work\.?\s*$/i, '')
    text = `${text.trimEnd()}\n\n${ATTACH_LINE}`
  }
  return `${text}\n\n${SIGNATURE}`
}
const rows = []
const failed = []
// Autopilot "auto": strong leads skip review and go straight to the send schedule (still capped by daily_max).
const AUTO = cfg.autopilot_mode === 'auto' && cfg.paused !== true
const AUTO_MIN = Number(cfg.auto_min_score) || 85

$input.all().forEach((item, i) => {
  const p = planFor(i)
  if (!p) return
  const res = item.json || {}
  try {
    const out = parseJson(res.choices[0].message.content)
    let subject = String(out.subject || '').replace(/\s+/g, ' ').trim().slice(0, 120)
    let body = String(out.body || '').replace(/\r\n/g, '\n').trim()
    // Follow-ups go out as replies in the original Gmail thread, so keep the original subject.
    if (p.kind === 'followup') subject = p.fallback_subject
    if (!subject || body.length < 40) throw new Error('empty subject or body')
    if (p.channel === 'email') body = finishEmail(body, p.kind)
    const auto = AUTO && p.channel === 'email' && Number(p.ai_score) >= AUTO_MIN
    rows.push({
      lead_id: p.lead_id, subject, body, sequence_step: p.sequence_step, channel: p.channel,
      status: auto ? 'scheduled' : 'pending_review', approved_at: auto ? new Date().toISOString() : null,
    })
  } catch (e) {
    const reason = res.error ? errorText(res.error) : String(e.message || e)
    failed.push({ lead: p.lead_id, kind: p.kind, message: `Draft failed: ${reason.slice(0, 200)}` })
  }
})

return [{ json: { rows, drafted: rows.length, failed } }]

// WF-3 "Run summary" (Code node, Run Once for All Items).
// One workflow_logs row per run. Drafts are counted in leads_scored (emails_sent stays 0:
// nothing is sent until you approve a draft in the dashboard).

const cfg = $('Config').first().json
// Input: every per-draft result collected by the "One at a time" loop (or the single empty plan item when
// there was nothing to draft).
const built = { drafted: 0, failed: [] }
const audit = []
for (const { json } of $input.all()) {
  built.drafted += Number(json.drafted) || 0
  if (Array.isArray(json.failed)) built.failed.push(...json.failed)
  for (const r of Array.isArray(json.rows) ? json.rows : []) {
    if (r.status === 'scheduled') audit.push({ actor: 'n8n:WF-3', action: 'auto_scheduled', lead_id: r.lead_id, details: { subject: r.subject, sequence_step: r.sequence_step } })
  }
}

return [{
  json: {
    // "audit": autopilot decisions (drafts scheduled without review), written to audit_log after the run log.
    audit,
    log: {
      workflow_name: 'WF-3-Outreach',
      status: built.drafted === 0 && built.failed.length > 0 ? 'failed' : 'success',
      leads_scraped: 0,
      leads_skipped: built.failed.length,
      leads_scored: built.drafted,
      emails_sent: 0,
      replies_detected: 0,
      errors: built.failed.length ? built.failed : null,
      started_at: cfg.started_at,
      finished_at: new Date().toISOString(),
    },
  },
}]

// "Settings" (Code node, Run Once for All Items).
// Starts from this workflow's Config node, then applies what you saved on the dashboard's Settings page
// (Supabase row settings.key = 'outreach'). Anything missing or invalid keeps the Config value.
const cfg = { ...$('Config').first().json }
const row = $input.first().json || {}
const saved = row.value && typeof row.value === 'object' && !Array.isArray(row.value) ? row.value : {}
const MAP = {"min_score":"min_score","drafts_per_run":"batch_size","follow_up_days":"follow_up_days","draft_dms":"draft_dms","sign_off":"sign_off","signature_name":"sender_name","company_name":"company_name","website":"website","paused":"paused","autopilot_mode":"autopilot_mode","auto_min_score":"auto_min_score","daily_max":"daily_max","daily_min":"daily_min","timezone":"timezone"} // dashboard key -> Config key (filled in per workflow by build.mjs)

const num = (min, max) => v => {
  const n = Number(v)
  return v !== '' && Number.isFinite(n) && n >= min && n <= max ? Math.round(n) : undefined
}
const bool = v => (typeof v === 'boolean' ? v : undefined)
const text = v => (typeof v === 'string' && v.trim() ? v.trim().slice(0, 120) : undefined)
const RULES = {
  min_score: num(0, 100),
  drafts_per_run: num(1, 50),
  daily_max: num(1, 500),
  daily_min: num(0, 500),
  send_window_start: num(0, 23),
  send_window_end: num(1, 24),
  send_on_weekends: bool,
  draft_dms: bool,
  // [] = no follow-ups ('0' is skipped by the planner); otherwise "4,7"
  follow_up_days: v => {
    const list = (Array.isArray(v) ? v : String(v).split(',')).map(Number).filter(n => Number.isInteger(n) && n > 0 && n <= 90)
    return list.length ? list.join(',') : '0'
  },
  timezone: v => {
    try {
      new Intl.DateTimeFormat('en-US', { timeZone: String(v) })
      return String(v)
    } catch {
      return undefined
    }
  },
  sign_off: text,
  signature_name: text,
  company_name: text,
  website: text,
  from_name: text,
  paused: bool,
  autopilot_mode: v => (['manual', 'digest', 'auto'].includes(v) ? v : undefined),
  auto_min_score: num(50, 100),
  digest_hour: num(0, 23),
  owner_email: v => (typeof v === 'string' && /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v.trim()) ? v.trim().toLowerCase() : undefined),
}

const applied = []
for (const [from, to] of Object.entries(MAP)) {
  if (saved[from] === undefined || saved[from] === null || !RULES[from]) continue
  const value = RULES[from](saved[from])
  if (value === undefined) continue
  cfg[to] = value
  applied.push(from)
}
if (cfg.send_window_start !== undefined && Number(cfg.send_window_start) >= Number(cfg.send_window_end)) {
  const base = $('Config').first().json
  cfg.send_window_start = base.send_window_start
  cfg.send_window_end = base.send_window_end
}
cfg.settings_applied = applied
return [{ json: cfg }]
